import { errors } from "@appport/protocol";
import { readExport, TIERS } from "../legacy/crm.mjs";

// Reads customers from the application's customer store.
//
// NOTE: I could not see the customer store module, so its location and API
// are assumptions. The previous version imported "../store/customers.mjs"
// statically, and the application failed to load because that file does not
// exist. The store is now loaded lazily, and its absence is tolerated:
//   - If STORE_PATH resolves and exposes a recognised lookup function, the
//     store is used.
//   - Otherwise this falls back to the legacy CRM export, so the handler
//     keeps working.
// Before treating the migration as complete, confirm the real store path and
// export name, then update STORE_PATH and findInStore.
const STORE_PATH = "../store/customers.mjs";

let storePromise;

function loadStore() {
  if (!storePromise) {
    storePromise = import(STORE_PATH).catch((err) => {
      if (err && err.code === "ERR_MODULE_NOT_FOUND") {
        return null;
      }
      throw err;
    });
  }
  return storePromise;
}

async function findInStore(store, customerId) {
  if (typeof store.getCustomer === "function") {
    return { found: true, record: await store.getCustomer(customerId) };
  }
  if (typeof store.findCustomer === "function") {
    return { found: true, record: await store.findCustomer(customerId) };
  }
  if (store.default && typeof store.default.get === "function") {
    return { found: true, record: await store.default.get(customerId) };
  }
  return { found: false, record: undefined };
}

function fromLegacy(customerId) {
  const row = readExport().find((r) => r.cust_id === customerId);
  if (!row) {
    return undefined;
  }
  return {
    customerId: row.cust_id,
    name: row.full_name,
    email: row.mail,
    tier: TIERS[row.level],
    since: row.created
  };
}

export async function lookupCustomer(input) {
  const store = await loadStore();

  let customer;
  let usedStore = false;
  if (store) {
    const result = await findInStore(store, input.customerId);
    if (result.found) {
      usedStore = true;
      const record = result.record;
      customer = record
        ? {
            customerId: record.customerId,
            name: record.name,
            email: record.email,
            tier: record.tier,
            since: record.since
          }
        : undefined;
    }
  }

  if (!usedStore) {
    customer = fromLegacy(input.customerId);
  }

  if (!customer) {
    throw errors.notFound(`no customer ${input.customerId}`);
  }
  return customer;
}
